"""Generate tests/torch_reference.rs from torch.optim.

Each case runs one torch optimizer for STEPS steps on float32 parameters with
a fixed gradient sequence (gradients do not depend on the parameters, so the
test checks the update rule alone). Run from the repository root:

    uv run --with torch==2.15.0 python tests/fixtures/gen_torch_reference.py > tests/torch_reference.rs
"""

import torch

N, STEPS = 6, 8


def lcg(seed):
    s = seed
    while True:
        s = (s * 6364136223846793005 + 1442695040888963407) % 2**64
        yield ((s >> 33) / 2**31) * 2.0 - 1.0


gen = lcg(7)
P0 = [next(gen) for _ in range(N)]
GRADS = [[next(gen) * 2.0 for _ in range(N)] for _ in range(STEPS)]

# (test name, descend builder expression, torch constructor)
CASES = [
    ("sgd", "Sgd::new(0.1)",
     lambda p: torch.optim.SGD(p, lr=0.1)),
    ("sgd_momentum", "Sgd::new(0.1).with_momentum(0.9)",
     lambda p: torch.optim.SGD(p, lr=0.1, momentum=0.9)),
    ("sgd_nesterov_weight_decay",
     "Sgd::new(0.05).with_momentum(0.8).with_nesterov(true).with_weight_decay(0.01)",
     lambda p: torch.optim.SGD(p, lr=0.05, momentum=0.8, nesterov=True, weight_decay=0.01)),
    ("adam", "Adam::new(0.01).with_betas(0.9, 0.999).with_epsilon(1e-8)",
     lambda p: torch.optim.Adam(p, lr=0.01, betas=(0.9, 0.999), eps=1e-8)),
    ("adam_l2",
     "Adam::new(0.01).with_betas(0.8, 0.99).with_epsilon(1e-6).with_weight_decay(0.1).with_decoupled(false)",
     lambda p: torch.optim.Adam(p, lr=0.01, betas=(0.8, 0.99), eps=1e-6, weight_decay=0.1)),
    ("adamw",
     "Adam::new(0.01).with_betas(0.9, 0.999).with_epsilon(1e-8).with_weight_decay(0.1).with_decoupled(true)",
     lambda p: torch.optim.AdamW(p, lr=0.01, betas=(0.9, 0.999), eps=1e-8, weight_decay=0.1)),
    # beta2 = 0.9 makes rho_t cross 5 within the run, covering both branches.
    ("radam", "Adam::new(0.01).with_betas(0.9, 0.9).with_epsilon(1e-8).with_rectified(true)",
     lambda p: torch.optim.RAdam(p, lr=0.01, betas=(0.9, 0.9), eps=1e-8)),
    ("adagrad",
     "Adagrad::new(0.1).with_epsilon(1e-10).with_weight_decay(0.01).with_initial_accumulator_value(0.1)",
     lambda p: torch.optim.Adagrad(p, lr=0.1, eps=1e-10, weight_decay=0.01, initial_accumulator_value=0.1)),
    ("rmsprop", "RmsProp::new(0.01).with_alpha(0.99).with_epsilon(1e-8)",
     lambda p: torch.optim.RMSprop(p, lr=0.01, alpha=0.99, eps=1e-8)),
    ("rmsprop_centered_momentum",
     "RmsProp::new(0.01).with_alpha(0.9).with_epsilon(1e-8).with_weight_decay(0.01).with_momentum(0.5).with_centered(true)",
     lambda p: torch.optim.RMSprop(p, lr=0.01, alpha=0.9, eps=1e-8, weight_decay=0.01, momentum=0.5, centered=True)),
]


def run(make):
    p = torch.tensor(P0, dtype=torch.float32, requires_grad=True)
    opt = make([p])
    out = []
    for g in GRADS:
        p.grad = torch.tensor(g, dtype=torch.float32)
        opt.step()
        out.append([float(x) for x in p.detach()])
    return out


def f32_literal(x):
    """Shortest decimal that parses back to the same f32."""
    target = torch.tensor(x, dtype=torch.float32)
    for digits in range(1, 10):
        text = f"{float(target):.{digits}g}"
        if torch.tensor(float(text), dtype=torch.float32) == target:
            break
    if "e" in text or "." in text:
        return text
    return text + ".0"


def arr(v):
    return "[" + ", ".join(f32_literal(x) for x in v) + "]"


print(f"""//! Optimizer trajectories against PyTorch `torch.optim` ({torch.__version__}).
//!
//! Generated by `tests/fixtures/gen_torch_reference.py`; do not edit by hand.
//! Each case feeds the same fixed gradient sequence to a descend optimizer
//! and to its torch counterpart, with every hyperparameter set explicitly,
//! and compares the parameters after each step.

use descend::{{Adagrad, Adam, Optimizer, RmsProp, Sgd}};

const P0: [f32; {N}] = {arr(P0)};

const GRADS: [[f32; {N}]; {STEPS}] = [
{chr(10).join("    " + arr(g) + "," for g in GRADS)}
];

fn check(name: &str, mut opt: impl Optimizer, expected: &[[f32; {N}]; {STEPS}]) {{
    let mut params = P0;
    for (step, (grads, want)) in GRADS.iter().zip(expected).enumerate() {{
        opt.step(&mut params, grads);
        for (i, (got, want)) in params.iter().zip(want).enumerate() {{
            // f32 arithmetic in a different order: allow a few ulps of drift.
            let tol = 1e-5 * want.abs().max(1.0);
            assert!(
                (got - want).abs() <= tol,
                "{{name}} step {{step}} param {{i}}: descend {{got}}, torch {{want}}"
            );
        }}
    }}
}}""")

for name, builder, make in CASES:
    traj = run(make)
    print(f"""
#[test]
fn {name}_matches_torch() {{
    let expected = [
{chr(10).join("        " + arr(r) + "," for r in traj)}
    ];
    check("{name}", {builder}, &expected);
}}""")
